<?php
require_once "config.php";require_once "includes/functions.php";wajibAdmin();$id=(int)($_GET["id"]??0);$edit=$id>0;$data=["tanggal"=>date("Y-m-d"),"id_pelanggan"=>"","total_belanja"=>""];
if($edit){$s=$pdo->prepare("SELECT * FROM tbl_transaksi WHERE id_transaksi=?");$s->execute([$id]);$data=$s->fetch();if(!$data){pesan("error","Transaksi tidak ditemukan.");header("Location: transaksi.php");exit;}}
$pelanggan=$pdo->query("SELECT id_pelanggan,nama_pelanggan FROM tbl_pelanggan ORDER BY nama_pelanggan")->fetchAll();$error="";
if($_SERVER["REQUEST_METHOD"]==="POST"){cekCsrf();$tanggal=$_POST["tanggal"]??"";$pid=(int)($_POST["id_pelanggan"]??0);$total=(float)($_POST["total_belanja"]??0);
if(!$tanggal||!$pid||$total<0)$error="Lengkapi formulir. Total belanja tidak boleh negatif.";else{try{if($edit){$s=$pdo->prepare("UPDATE tbl_transaksi SET tanggal=?,id_pelanggan=?,total_belanja=? WHERE id_transaksi=?");$s->execute([$tanggal,$pid,$total,$id]);pesan("success","Transaksi berhasil diperbarui.");}else{$s=$pdo->prepare("INSERT INTO tbl_transaksi(tanggal,id_pelanggan,total_belanja) VALUES(?,?,?)");$s->execute([$tanggal,$pid,$total]);pesan("success","Transaksi berhasil ditambahkan.");}header("Location: transaksi.php");exit;}catch(PDOException $ex){$error="Transaksi gagal disimpan. Pastikan pelanggan tersedia dan aturan Trigger terpenuhi.";}}$data=["tanggal"=>$tanggal,"id_pelanggan"=>$pid,"total_belanja"=>$total];}
$pageTitle=$edit?"Edit Transaksi":"Tambah Transaksi";require "includes/header.php";
?>
<div class="page-intro"><div><span class="eyebrow">FORMULIR PENJUALAN</span><h2><?= e($pageTitle) ?></h2><p>Masukkan informasi transaksi dengan benar.</p></div><a class="btn btn-outline" href="transaksi.php">← Kembali</a></div>
<div class="form-panel panel"><div class="form-section-title"><span class="stat-icon peach">▤</span><div><h3>Informasi Transaksi</h3><p>Pastikan pelanggan dan nilai transaksi sesuai.</p></div></div><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?>
<form method="post" class="data-form"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><div class="form-grid"><div class="field"><label>Tanggal Transaksi</label><input class="input" type="date" name="tanggal" value="<?= e($data["tanggal"]) ?>" required></div><div class="field"><label>Nama Pelanggan</label><select class="input" name="id_pelanggan" required><option value="">Pilih pelanggan</option><?php foreach($pelanggan as $p): ?><option value="<?= e($p["id_pelanggan"]) ?>" <?= (string)$data["id_pelanggan"]===(string)$p["id_pelanggan"]?"selected":"" ?>><?= e($p["nama_pelanggan"]) ?></option><?php endforeach; ?></select></div><div class="field full-field"><label>Total Belanja (Rp)</label><input class="input" type="number" name="total_belanja" min="0" step="0.01" value="<?= e($data["total_belanja"]) ?>" placeholder="Contoh: 150000" required><small>Nilai negatif akan ditolak oleh validasi Trigger BAB 5.</small></div></div><div class="form-actions"><a class="btn btn-outline" href="transaksi.php">Batal</a><button class="btn btn-primary"><?= $edit?"Simpan Perubahan":"Simpan Transaksi" ?></button></div></form></div>
<?php require "includes/footer.php"; ?>
